#include <bits/stdc++.h>
using namespace std;using U=uint64_t;
struct Cell{string id;int n,k,m;vector<pair<int,int>>es;vector<int>ports;};
U adj[64];int N,baseN;vector<int>oldports;Cell *g;ofstream out;unsigned long long nodes=0,hits=0,visits=0,pr[4]={};bool stopped=false;chrono::steady_clock::time_point began;double budget=12;
bool path(int u,int t,int rem,U seen){visits++;if(rem==1)return adj[u]>>t&1;U m=adj[u]&~seen&~(1ULL<<t);while(m){int v=__builtin_ctzll(m);m&=m-1;if(path(v,t,rem-1,seen|(1ULL<<v)))return true;}return false;}
bool safe(int a,int b){for(int j=0,L=4;L<=N;L*=2,j++){if(path(a,b,L-1,1ULL<<a)){pr[j]++;return false;}}return true;}
void save(){hits++;int m=0;for(int v=0;v<N;v++)m+=__builtin_popcountll(adj[v]);out<<g->id<<" "<<N<<" "<<m/2<<"\n";for(int v=0;v<N;v++)for(int w=v+1;w<N;w++)if(adj[v]>>w&1)out<<v<<" "<<w<<"\n";out.flush();if(hits>=100)stopped=true;}
void dfs(int dep,U used){if(stopped)return;nodes++;if((nodes&1023)==0&&chrono::duration<double>(chrono::steady_clock::now()-began).count()>budget){stopped=true;return;}if(dep==g->k){save();return;}int a=g->ports[dep]+baseN;for(int b:oldports){if(used>>b&1)continue;if(!safe(a,b))continue;adj[a]|=1ULL<<b;adj[b]|=1ULL<<a;dfs(dep+1,used|1ULL<<b);adj[a]^=1ULL<<b;adj[b]^=1ULL<<a;if(stopped)return;}}
int main(int argc,char**argv){if(argc<4)return 2;ifstream f(argv[1]);string tag;int bm=0;vector<pair<int,int>>be;while(f>>tag){if(tag=="p"){string z;f>>z>>baseN>>bm;}else if(tag=="e"){int a,b;f>>a>>b;be.emplace_back(a-1,b-1);}else{string s;getline(f,s);}}vector<int>degree(baseN);for(auto[a,b]:be){degree[a]++;degree[b]++;}for(int v=0;v<baseN;v++)if(degree[v]==2)oldports.push_back(v);ifstream cf(argv[2]);int gc;cf>>gc;vector<Cell>cs(gc);for(auto&x:cs){cf>>x.id>>x.n>>x.k>>x.m;x.ports.resize(x.k);for(auto&v:x.ports)cf>>v;for(int j=0,a,b;j<x.m;j++){cf>>a>>b;x.es.emplace_back(a,b);}}out.open(argv[3]);if(argc>4)budget=stod(argv[4]);began=chrono::steady_clock::now();for(auto&c:cs){g=&c;N=baseN+c.n;if(N>63||c.k>(int)oldports.size())continue;fill(adj,adj+64,0);for(auto[a,b]:be){adj[a]|=1ULL<<b;adj[b]|=1ULL<<a;}for(auto[a,b]:c.es){a+=baseN;b+=baseN;adj[a]|=1ULL<<b;adj[b]|=1ULL<<a;}auto prev=nodes;dfs(0,0);cerr<<c.id<<" nodes "<<nodes-prev<<" hits_total "<<hits<<" stopped "<<stopped<<"\n";if(stopped)break;}cerr<<"FINAL nodes "<<nodes<<" hits "<<hits<<" visits "<<visits<<" exhaustive "<<!stopped<<" seconds "<<chrono::duration<double>(chrono::steady_clock::now()-began).count();for(int i=0;i<4;i++)cerr<<" prune"<<(4<<i)<<":"<<pr[i];cerr<<"\n";}
